1	// Red-first fixture tests for the gcec pack's checks, runnable by this repo's own
2	// `npm test` (no imports from the gitignored .claudinite mount — see the check
3	// module's header). Each rule is shown firing on a violating fixture and staying
4	// quiet on a clean one.
5	import test from 'node:test';
6	import assert from 'node:assert/strict';
7	import testOfflineListSync from './test-offline-list-sync.mjs';
8	import customSourcesFlat from './custom-sources-flat.mjs';
9	import npmTestGlobCoverage from './npm-test-glob-coverage.mjs';
10	import pipelineSiteAgnostic from './pipeline-site-agnostic.mjs';
11	
12	function ctx({ files = [], pkg }) {
13	  const disk = new Set([...files, 'package.json']);
14	  return {
15	    files,
16	    read: (p) => (p === 'package.json' ? JSON.stringify(pkg) : null),
17	    exists: (p) => disk.has(p),
18	  };
19	}
20	
21	const pkgWith = (offline) => ({ scripts: { 'test:offline': `node --test ${offline.join(' ')}` } });
22	
23	test('test-offline-list-sync: fires when a mirror test is missing from the list', () => {
24	  const findings = testOfflineListSync.run(
25	    ctx({
26	      files: ['extension-test/a.test.js', 'extension-test/b.test.js'],
27	      pkg: pkgWith(['extension-test/a.test.js']),
28	    }),
29	  );
30	  assert.equal(findings.length, 1);
31	  assert.match(findings[0].what, /missing extension-test\/b\.test\.js/);
32	  assert.equal(findings[0].severity, 'blocking');
33	});
34	
35	test('test-offline-list-sync: fires when the list names a file that does not exist', () => {
36	  const findings = testOfflineListSync.run(
37	    ctx({
38	      files: ['extension-test/a.test.js'],
39	      pkg: pkgWith(['extension-test/a.test.js', 'extension-test/gone.test.js']),
40	    }),
41	  );
42	  assert.equal(findings.length, 1);
43	  assert.match(findings[0].what, /extension-test\/gone\.test\.js, which does not exist/);
44	});
45	
46	test('test-offline-list-sync: quiet when list and tree agree (non-mirror entries ignored)', () => {
47	  const findings = testOfflineListSync.run(
48	    ctx({
49	      files: ['extension-test/a.test.js', 'dev/build/test/other.test.js'],
50	      pkg: pkgWith(['extension-test/a.test.js', 'dev/build/release/shipping-files.test.js']),
51	    }),
52	  );
53	  assert.deepEqual(findings, []);
54	});
55	
56	test('test-offline-list-sync: quiet when package.json has no test:offline script', () => {
57	  const findings = testOfflineListSync.run(
58	    ctx({ files: ['extension-test/a.test.js'], pkg: { scripts: {} } }),
59	  );
60	  assert.deepEqual(findings, []);
61	});
62	
63	// A context whose files ARE the keys of a path → content map, for the rules that
64	// read file text rather than package.json.
65	const treeCtx = (tree) => ({
66	  files: Object.keys(tree),
67	  read: (p) => (p in tree ? tree[p] : null),
68	  exists: (p) => p in tree,
69	});
70	
71	test('custom-sources-flat: fires on a subdirectory, a non-source file, and a pipeline file in custom/', () => {
72	  const findings = customSourcesFlat.run(
73	    treeCtx({
74	      'extension/event-extractors/custom/barby.js': '',
75	      'extension/event-extractors/custom/shared/util.js': '',
76	      'extension/event-extractors/custom/README.md': '',
77	      'extension/event-extractors/custom/generic-extractor.js': '',
78	    }),
79	  );
80	  assert.equal(findings.length, 3);
81	  assert.match(findings[0].what, /sits in a subdirectory/);
82	  assert.match(findings[1].what, /is not a per-site source/);
83	  assert.match(findings[2].what, /is a pipeline file/);
84	  assert.ok(findings.every((f) => f.severity === 'blocking'));
85	});
86	
87	test('custom-sources-flat: quiet on a flat tree of per-site sources beside the pipeline', () => {
88	  const findings = customSourcesFlat.run(
89	    treeCtx({
90	      'extension/event-extractors/custom/barby.js': '',
91	      'extension/event-extractors/custom/tel-aviv.js': '',
92	      'extension/event-extractors/generic-extractor.js': '',
93	      'extension/event-extractors/registry.js': '',
94	      'extension/event-extractors/helpers/dates.js': '',
95	      'extension/event-extractors/load-order.generated.json': '',
96	    }),
