98	  assert.deepEqual(findings, []);
99	});
100	
101	// npm-test-glob-coverage reads package.json's `test` (and `test:e2e`) scripts, so its
102	// fixtures pair a file list with a scripts object — the real shape of both scripts,
103	// quoted globs included.
104	const globCtx = (files, scripts) =>
105	  ctx({ files, pkg: { scripts } });
106	
107	const SCRIPTS = {
108	  test: 'node --disable-warning=X --test "extension-test/**/*.test.js" "dev/build/test/**/*.test.js" ".claudinite/local/packs/**/*.test.mjs" "dev/requirements/logic/**/*.test.js" dev/requirements/requirements-coverage.test.js',
109	  'test:e2e': 'node --test "dev/requirements/heavy/**/*.test.js"',
110	};
111	
112	test('npm-test-glob-coverage: fires on a test file no `test` pattern reaches', () => {
113	  const findings = npmTestGlobCoverage.run(
114	    globCtx(
115	      ['extension-test/host-policy.test.js', 'dev/security/csp.test.js'],
116	      SCRIPTS,
117	    ),
118	  );
119	  assert.equal(findings.length, 1);
120	  assert.equal(findings[0].file, 'dev/security/csp.test.js');
121	  assert.match(findings[0].what, /reached by no pattern/);
122	  assert.equal(findings[0].severity, 'blocking');
123	});
124	
125	test('npm-test-glob-coverage: quiet when every pattern shape reaches its files', () => {
126	  const findings = npmTestGlobCoverage.run(
127	    globCtx(
128	      [
129	        'extension-test/host-policy.test.js', // `**/` must match ZERO directories too
130	        'extension-test/events-popup/popup.test.js',
131	        'dev/build/test/load-order-generated.test.js',
132	        '.claudinite/local/packs/gcec/pack.test.mjs', // .mjs counts as a test file
133	        'dev/requirements/logic/product-requirements.test.js',
134	        'dev/requirements/requirements-coverage.test.js', // a literal path, not a glob
135	        'extension/host-policy.js', // not a test file at all
136	      ],
137	      SCRIPTS,
138	    ),
139	  );
140	  assert.deepEqual(findings, []);
141	});
142	
143	test('npm-test-glob-coverage: the heavy e2e suite is exempt via scripts["test:e2e"]', () => {
144	  const heavy = 'dev/requirements/heavy/extension-load.chrome.test.js';
145	  assert.deepEqual(npmTestGlobCoverage.run(globCtx([heavy], SCRIPTS)), []);
146	  // …and only because test:e2e declares it: drop that script and the carve-out goes.
147	  const findings = npmTestGlobCoverage.run(globCtx([heavy], { test: SCRIPTS.test }));
148	  assert.equal(findings.length, 1);
149	  assert.equal(findings[0].file, heavy);
150	});
151	
152	test('npm-test-glob-coverage: quiet when the test script is not a `node --test` runner', () => {
153	  const findings = npmTestGlobCoverage.run(
154	    globCtx(['dev/security/csp.test.js'], { test: 'jest' }),
155	  );
156	  assert.deepEqual(findings, []);
157	});
158	
159	// pipeline-site-agnostic reads the host list out of the repo, so every fixture
160	// tree carries a host-lists.json — the check follows that declaration, never a
161	// copy of it.
162	const HOSTS = JSON.stringify({
163	  supportedDomains: ['stubhub.com', 'tel-aviv.gov.il', 'visit.tel-aviv.gov.il', 'lu.ma'],
164	});
165	const pipelineCtx = (tree) => treeCtx({ 'extension/host-lists.json': HOSTS, ...tree });
166	
167	test('pipeline-site-agnostic: fires on a host in shipped pipeline code, in the generic extractor and in a helper', () => {
168	  const findings = pipelineSiteAgnostic.run(
169	    pipelineCtx({
170	      'extension/event-extractors/generic-extractor.js':
171	        'function read(doc) {\n  if (host.endsWith("stubhub.com")) return special(doc);\n  return generic(doc);\n}\n',
172	      'extension/event-extractors/helpers/derive-timezone.js':
173	        'const OVERRIDE = { "visit.tel-aviv.gov.il": "Asia/Jerusalem" };\n',
174	    }),
175	  );
176	  assert.equal(findings.length, 2);
177	  assert.equal(findings[0].file, 'extension/event-extractors/generic-extractor.js');
178	  assert.equal(findings[0].line, 2); // the blanked comments keep line numbers true
179	  assert.match(findings[0].what, /names the supported site stubhub\.com/);
180	  // the longest matching entry wins, not the one it contains
181	  assert.match(findings[1].what, /visit\.tel-aviv\.gov\.il/);
182	  assert.ok(findings.every((f) => f.severity === 'blocking'));
183	});
184	
185	test('pipeline-site-agnostic: fires on a host hidden in a URL string (the `//` must not read as a comment)', () => {
186	  const findings = pipelineSiteAgnostic.run(
187	    pipelineCtx({
188	      'extension/event-extractors/assemble-events.js':
189	        'const FEED = "https://lu.ma/api/events";\n',
190	    }),
191	  );
192	  assert.equal(findings.length, 1);
193	  assert.equal(findings[0].line, 1);
194	  assert.match(findings[0].what, /lu\.ma/);
195	});
196	
197	test('pipeline-site-agnostic: quiet when the sites are only cited in comments, or live in custom/', () => {
198	  const findings = pipelineSiteAgnostic.run(
199	    pipelineCtx({
200	      // citing where a generic pattern was observed is how this codebase records
201	      // evidence — both comment forms, and one on the same line as real code
202	      'extension/event-extractors/generic-extractor.js':
203	        '// or is merely the site\'s domain ("stubhub.com" is not a venue).\n' +
204	        '/* seen on visit.tel-aviv.gov.il\n   and lu.ma */\n' +
205	        'const venue = readVenue(doc); // not stubhub.com-specific\n',
206	      // per-site knowledge belongs here, and this check must never flag it
207	      'extension/event-extractors/custom/stubhub.js':
208	        'GCal.sources.push({ matches: (h) => /(^|\\.)stubhub\\.com$/.test(h) });\n',
209	      // a host-shaped substring is not the host
210	      'extension/event-extractors/helpers/text.js': 'const s = "notstubhub.combo";\n',
211	      // non-.js pipeline files are out of scope
212	      'extension/event-extractors/load-order.generated.json': '["stubhub.com"]',
213	    }),
214	  );
215	  assert.deepEqual(findings, []);
216	});
217	
218	test('pipeline-site-agnostic: quiet when the host list is missing or declares nothing', () => {
219	  const tree = {
220	    'extension/event-extractors/generic-extractor.js': 'if (h === "stubhub.com") {}\n',
221	  };
222	  assert.deepEqual(pipelineSiteAgnostic.run(treeCtx(tree)), []);
223	  assert.deepEqual(
224	    pipelineSiteAgnostic.run(treeCtx({ ...tree, 'extension/host-lists.json': '{"supportedDomains":[]}' })),
225	    [],
226	  );
227	});
